param([Parameter(Mandatory=$true)][string]$MameExecutable,[Parameter(Mandatory=$true)][string]$RomDirectory,[Parameter(Mandatory=$true)][string]$RunDirectory)
$ErrorActionPreference='Stop';$run=[IO.Path]::GetFullPath($RunDirectory);if(Test-Path $run){throw 'Fresh isolated directory required'};New-Item -ItemType Directory $run|Out-Null;foreach($name in @('cfg','nvram','inp','snap','comments','state','diff')){New-Item -ItemType Directory "$run/$name"|Out-Null}
$commands=[Collections.Generic.List[string]]::new();$cases=[Collections.Generic.List[object]]::new();$commands.Add('bpset 28fe')
$body=Get-Content "$PSScriptRoot/../src/FruitMachineLab.Runtime/Mpu4Timer1DispatchExecution.cs" -Raw
foreach($pc in ([regex]::Matches($body,'\(0x([0-9A-F]{4}),"')|ForEach-Object {[Convert]::ToInt32($_.Groups[1].Value,16)}|Sort-Object -Unique|Where-Object {$_ -ne 0xFE70})){$commands.Add(('bpset {0:X},1,{{printf "DI id=%X pc=%04X cycle=%016X bytes=%02X%02X%02X%02X%02X\n",temp1,pc,totalcycles,b@pc,b@(pc+1),b@(pc+2),b@(pc+3),b@(pc+4);go}}' -f $pc))}
foreach($variant in 0..7){foreach($level in 0..7){$id=$cases.Count;$savedU=@(0x524,0x525,0x670,0x7C8,0x8000,0xFFFF,0,0x7FFF)[$variant];$cases.Add([ordered]@{id=$id;savedU=$savedU})
 $commands.Add(('temp1=0x{0:X};cc=0x50;dp=0;s=0x700;u=0x700;w@708=0x{1:X};b@f1=0;b@3f=0;b@b03=4;b@901=1;b@900=1;b@902=0;b@903=1;b@900=0x02;pc=0xfe70' -f $id,$savedU))
 $commands.Add('printf "DS id=%X pc=%04X cycle=%016X bytes=%02X%02X%02X%02X%02X\n",temp1,pc,totalcycles,b@pc,b@(pc+1),b@(pc+2),b@(pc+3),b@(pc+4)');$commands.Add('go');$commands.Add('printf "DF id=%X pc=%04X cycle=%016X s=%04X savedu=%04X\n",temp1,pc,totalcycles,s,w@708')
}}
$commands.Add('quit');$commands|Set-Content "$run/debugger.cmd";$cases|ConvertTo-Json|Set-Content "$run/cases.json";[ordered]@{classification='Synthetic original timer1 FE70 dispatch; bank0/noIC4, masked CPU IRQ/FIRQ, injected saved-U frame and pending timer1 flag from hardware control02/latch1 (IRQ disabled to prevent recursive short-period IRQ after ANDCC). SWI2 handler and ROM option unpatched. Stop before28FE';mame_sha256=(Get-FileHash $MameExecutable).Hash}|ConvertTo-Json|Set-Content "$run/provenance.json"
$arguments=@('m4addr','-noreadconfig','-rompath',$RomDirectory,'-cfg_directory',"$run/cfg",'-nvram_directory',"$run/nvram",'-input_directory',"$run/inp",'-snapshot_directory',"$run/snap",'-comment_directory',"$run/comments",'-state_directory',"$run/state",'-diff_directory',"$run/diff",'-debug','-debugger','windows','-debugscript',"$run/debugger.cmd",'-debuglog','-video','none','-sound','none','-window','-skip_gameinfo','-nothrottle','-seconds_to_run','30');$arguments|ConvertTo-Json|Set-Content "$run/arguments.json"
Push-Location $run;try{& $MameExecutable @arguments *> console.txt;$code=$LASTEXITCODE;$code|Set-Content exit-code.txt}finally{Pop-Location};if($code -ne 0 -or (Select-String "$run/debug.log" -Pattern '^Error ' -Quiet)){throw 'Invalid dispatch capture'};Write-Output $run
